bool swapped;
for (std::size_t i = 0; i + 1 < n; ++i) {
swapped = false;
for (std::size_t j = 0; j + 1 < n - i; ++j) {
if (arr[j] > arr[j + 1]) {
std::swap(arr[j], arr[j + 1]);
swapped = true;
}
}
if (!swapped) break;
}
}

